/* Condições contratuais e liberação das retenções, sem criar novo faturamento. */
(function(root){'use strict';const D=root.Obras,h=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),money=n=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(n).replace(/\s/g,''),$=q=>document.querySelector(q);let api,pending=false,snapshot;
function eligible(groups){return groups.filter(g=>!g.released&&g.retained>0&&g.held>0&&g.records.some(m=>m.status==='Aprovada')&&g.records.every(m=>['Aprovada','Glosada'].includes(m.status)))}
function releaseAll(state,project){
 if(!project||project==='all'||!state.projects.some(p=>p.id===project))throw Error('Selecione uma obra específica para liberar retenções em lote.');
 const groups=eligible(D.measurementGroups(state,project));if(!groups.length)throw Error('Não há retenções aprovadas e pendentes de liberação nesta obra.');
 let next=D.clone(state);for(const g of groups)next=D.measurementTerms(next,project,g.number,{type:g.type,rate:g.rate,released:true});
 D.validateMeasurementFinances(next);D.validateReceivableInstallments(next);
 next.history.unshift({id:'RET-BATCH-'+Date.now()+'-'+Math.random().toString(36).slice(2),time:new Date().toISOString(),kind:'retentionBatch',record:project,action:'Liberar todas as retenções da obra',before:{numbers:groups.map(g=>g.number)},after:{count:groups.length,amount:D.sum(groups,g=>g.held)}});
 return next;
}
function render(s,p){const groups=D.measurementGroups(s,p),toRelease=p==='all'?[]:eligible(groups),pendingAmount=D.sum(toRelease,g=>g.held),unreleased=D.sum(groups.filter(g=>!g.released),g=>g.held),released=D.sum(groups.filter(g=>g.released),g=>g.held);
 const bulk=p==='all'?'<p class="section-note">Selecione uma obra no topo da página para liberar todas as suas retenções.</p>':(toRelease.length?'<div class="actions"><button type="button" class="button primary" data-action="retention-release-all">Liberar todas as retenções ('+toRelease.length+')</button><span>Valor a liberar: <strong>'+money(pendingAmount)+'</strong></span></div>':'<p class="section-note">Não há retenções aprovadas pendentes de liberação para esta obra.</p>');
 return '<section class="panel"><div class="panel-head"><h2>Entrada, medições e retenções</h2></div><div class="notice neutral"><strong>Retenção ainda bloqueada: '+money(unreleased)+'</strong> · Liberado a receber: '+money(released)+' · Retenção recebida: '+money(D.sum(groups,g=>g.retentionReceived))+'</div><div class="notice neutral">A entrada contratual é cadastrada separadamente e amortizada nas medições posteriores. A retenção é calculada sobre o bruto aprovado de cada medição. Liberar retenções permite seu lançamento em Contas a Receber, mas não registra o pagamento: a baixa precisa ser feita depois, em Recebimentos, como Retenção.</div>'+bulk+'<div class="table-wrap"><table><thead><tr><th>Obra / medição</th><th>Tipo</th><th>Bruto lançado</th><th>Bruto aprovado</th><th>Retenção</th><th>Líquido aprovado</th><th>Líquido a receber</th><th>Retido a receber</th><th>Situação da retenção</th><th></th></tr></thead><tbody>'+groups.map(g=>'<tr><td>'+h(s.projects.find(p=>p.id===g.project)?.name)+'<br><strong>'+h(g.number)+'</strong></td><td>'+h(g.type)+'</td><td>'+money(g.gross)+'</td><td>'+money(g.approved)+'</td><td>'+money(g.retained)+'<br>'+h(g.rate)+'%</td><td>'+money(g.net)+'</td><td>'+money(g.balance)+'</td><td>'+money(g.held)+'</td><td>'+(!g.retained?'Sem retenção':g.held===0?'Recebida':g.released?'Liberada para receber':'Retida')+'</td><td><button class="button secondary" data-action="retention-terms:'+h(g.records[0].id)+'">Condições / liberar</button></td></tr>').join('')+'</tbody></table></div>'+(groups.length?'':'<div class="empty">Nenhuma medição registrada.</div>')+'</section>';
}
async function releaseAllAction(){
 if(pending)return;
 snapshot=D.clone(api.getState());const project=api.getProject();
 let options;try{if(project==='all')throw Error('Selecione uma obra específica.');options=eligible(D.measurementGroups(snapshot,project));if(!options.length)throw Error('Não há retenções aprovadas pendentes de liberação.')}catch(err){api.toast(err.message);return}
 const amount=D.sum(options,g=>g.held),projectName=snapshot.projects.find(p=>p.id===project)?.name||'obra';
 if(!root.confirm('Liberar todas as retenções de '+projectName+'?\\n\\n'+options.length+' medição(ões)\\nValor: '+money(amount)+'\\n\\nO valor ficará disponível em Contas a Receber. Esta ação NÃO registra um pagamento.'))return;
 try{
  if(JSON.stringify(api.getState())!==JSON.stringify(snapshot))throw Error('Os dados mudaram. Atualize a página e confira antes de liberar.');
  const next=releaseAll(snapshot,project);pending=true;
  if(await api.save(next)===false)throw Error('O servidor não confirmou a liberação. Atualize e confira o saldo antes de tentar novamente.');
  pending=false;api.render();api.toast(options.length+' retenção(ões) liberada(s), total de '+money(amount)+'.');
 }catch(err){pending=false;api.toast(err.message||String(err))}
}
function isDirty(){return !!$('#reader')?.open&&!!$('#readerContent .retention-editor')}
function open(recordId){snapshot=D.clone(api.getState());let m=snapshot.measurements.find(m=>m.id===recordId),g=m&&D.measurementGroups(snapshot,m.project).find(g=>g.number===m.number);if(!g)throw Error('Medição não encontrada.');$('#readerTitle').textContent='Condições da medição '+g.number;$('#readerContent').innerHTML='<form id="retentionForm" class="reader-page retention-editor"><p>Estas condições valem para todos os itens desta medição. Alterar o percentual da obra afeta somente novas medições. Medições antigas permanecem com o percentual registrado.</p><label>Tipo<select id="retentionType"><option '+(g.type==='Medição'?'selected':'')+'>Medição</option><option '+(g.type==='Entrada'?'selected':'')+'>Entrada</option></select></label><label>Retenção (%)<input id="retentionRate" type="number" min="0" max="100" step="0.01" required value="'+g.rate+'"></label><label class="inline-check"><input id="retentionReleased" type="checkbox" '+(g.released?'checked':'')+'> Retenção liberada contratualmente para recebimento</label><p>Bruto aprovado: <strong>'+money(g.approved)+'</strong>. Retenção recebida: <strong>'+money(g.retentionReceived)+'</strong>.</p><p>O sistema impede reduzir a cobertura de valores já recebidos. Para corrigir um recebimento, edite-o primeiro na aba Recebimentos.</p><p id="retentionError" role="alert" class="red-text"></p><button class="button primary" type="submit" id="retentionSave">Salvar condições</button></form>';$('#reader').showModal();$('#retentionForm').onsubmit=async e=>{e.preventDefault();if(pending)return;try{if(JSON.stringify(api.getState())!==JSON.stringify(snapshot))throw Error('Os dados mudaram. Reabra as condições antes de salvar.');let text=$('#retentionRate').value;if(!text.trim())throw Error('Informe o percentual de retenção.');let next=D.measurementTerms(snapshot,g.project,g.number,{type:$('#retentionType').value,rate:Number(text),released:$('#retentionReleased').checked});pending=true;$('#retentionSave').disabled=true;if(await api.save(next)===false)throw Error('O servidor não confirmou a alteração. Atualize antes de tentar novamente.');pending=false;$('#reader').close();api.render();api.toast('Condições e retenção atualizadas.')}catch(err){pending=false;$('#retentionSave').disabled=false;$('#retentionError').textContent=err.message}}}
root.EngefexRetentions={render,isDirty,eligible,releaseAll,busy:()=>pending,init:options=>{api=options},handle:action=>{if(action==='retention-release-all'){releaseAllAction();return true}if(!action?.startsWith('retention-terms:'))return false;try{open(action.slice(16))}catch(e){api.toast(e.message)}return true}};
})(window);
